              {"id": "pos_enc", "label": "Positional Encoding"}
            ],
            "connections": [
              {"from": "pos_enc", "to": "enc", "label": "adds position"},
              {"from": "enc", "to": "self_attn", "label": "self‑attention"},
              {"from": "self_attn", "to": "ffn", "label": "feed‑forward"},
              {"from": "ffn", "to": "dec", "label": "passes to decoder"},
              {"from": "dec", "to": "self_attn", "label": "decoder self‑attention"},
              {"from": "dec", "to": "enc", "label": "cross‑attention"}
            ]
          }
        }
      ]
    },
    {
      "title": "Agentic AI Goal‑Oriented Planning Sequence",
      "source_segment_ids": ["FCT_0052", "FCT_0053", "FCT_0050"],
      "mode": "text_and_visual",
      "remaining_text": "",
      "visuals": [
        {
          "source_segment_ids": ["FCT_0052", "FCT_0053", "FCT_0050"],
          "needs_review": false,
          "missing_information": null,
          "evidence": [
            {
              "note_id": "FCT_0052",
              "exact_quote": "Agentic AI systems provide the LLM with access to knowledge, memory, and external tools, and use a reasoning model to create a plan and execute the steps."
            },
            {
              "note_id": "FCT_0053",
              "exact_quote": "Goal‑oriented planning is a characteristic of agentic AI where the user provides a goal (e.g., onboarding a new intern) and the system autonomously decides the sequence of actions to achieve it."
            },
            {
              "note_id": "FCT_0050",
              "exact_quote": "When the chatbot is given a more complex goal, such as onboarding a new intern, it can perform multi‑step planning and execute actions like creating an onboarding checklist, scheduling a welcome meeting, and sending access requests."
            }
          ],
          "payload": {
